import React, { useEffect, useState } from "react";
import { api, fmt } from "../lib/api";
import { useAuth } from "../context/AuthContext";
import { toast } from "sonner";

export default function Mentorship() {
  const { user } = useAuth();
  const [list, setList] = useState([]);
  const [tab, setTab] = useState(user?.role === "alumni" ? "in" : "out");
  const load = async () => { const { data } = await api.get("/mentorship/my"); setList(data); };
  useEffect(() => { load(); }, []);
  const act = async (id, status) => {
    try { await api.patch(`/mentorship/${id}`, { status }); toast.success(status); load(); }
    catch (e) { toast.error(fmt(e.response?.data?.detail)); }
  };
  const incoming = list.filter(r => r.alumniId === user?.id);
  const outgoing = list.filter(r => r.studentId === user?.id);
  const rows = tab === "in" ? incoming : outgoing;
  return (
    <div style={{ maxWidth: 900, margin: "0 auto", padding: "3rem 2rem" }}>
      <div className="overline">Mentorship</div>
      <h1 className="font-serif" style={{ fontSize: "2.5rem", color: "var(--ivy)", margin: "8px 0 2rem" }}>Requests & Responses</h1>
      <div style={{ display: "flex", gap: 8, borderBottom: "1px solid var(--border)", marginBottom: 24 }}>
        <button className="btn-outline" style={{ border: "none", borderBottom: tab === "in" ? "2px solid var(--ivy)" : "none" }} onClick={() => setTab("in")}>Incoming ({incoming.length})</button>
        <button className="btn-outline" style={{ border: "none", borderBottom: tab === "out" ? "2px solid var(--ivy)" : "none" }} onClick={() => setTab("out")}>Outgoing ({outgoing.length})</button>
      </div>
      {rows.length === 0 ? <p style={{ color: "var(--muted)" }}>No requests.</p> :
        rows.map(r => (
          <div key={r._id} className="card-editorial" style={{ padding: 24, marginBottom: 16 }}>
            <div className="overline">{tab === "in" ? `From ${r.studentName}` : `To ${r.alumniName}`}</div>
            <p style={{ color: "var(--muted)", marginTop: 8 }}>{r.message}</p>
            <span className="tag" style={{ marginTop: 12, display: "inline-block" }}>{r.status}</span>
            {tab === "in" && r.status === "pending" && (
              <div style={{ marginTop: 16, display: "flex", gap: 8 }}>
                <button className="btn-primary" onClick={() => act(r._id, "accepted")}>Accept</button>
                <button className="btn-outline" onClick={() => act(r._id, "rejected")}>Decline</button>
              </div>
            )}
          </div>
        ))}
    </div>
  );
}
